--  alter table to add appscode to separate workflow from different applications
ALTER TABLE `clickargo2`.`T_CK_FORM_CONTROL` 
ADD COLUMN `CTRL_APPS_CODE` VARCHAR(35) NOT NULL AFTER `CTRL_UID_LUPD`;

-- update records for new column
SET SQL_SAFE_UPDATES = 0;
UPDATE T_CK_FORM_CONTROL
	SET CTRL_APPS_CODE  = 'CKDO'
    where CTRL_ENTITY_TYPE like '%DOI%';
SET SQL_SAFE_UPDATES = 1;
    
SET SQL_SAFE_UPDATES = 0;
UPDATE T_CK_FORM_CONTROL
	SET CTRL_APPS_CODE  = 'CKT'
    where CTRL_APPS_CODE ='';
SET SQL_SAFE_UPDATES = 1;
    
-- alter table to add foreign key constraint to tcoreapps
ALTER TABLE `clickargo2`.`T_CK_FORM_CONTROL` 
ADD INDEX `FK_CK_FORM_CONTROL_CORE_APPS_idx` (`CTRL_APPS_CODE` ASC) VISIBLE;
;
ALTER TABLE `clickargo2`.`T_CK_FORM_CONTROL` 
ADD CONSTRAINT `FK_CK_FORM_CONTROL_CORE_APPS`
  FOREIGN KEY (`CTRL_APPS_CODE`)
  REFERENCES `clickargo2`.`T_CORE_APPS` (`APPS_CODE`)
  ON DELETE NO ACTION
  ON UPDATE NO ACTION;


